diff --git a/solution.ts b/solution.ts
index 6b67e51..4ab6cda 100644
--- a/solution.ts
+++ b/solution.ts
@@ -1,8 +1,25 @@
 export function parseQueryString(qs: string): Record<string, string | string[]> {
   const result: Record<string, string | string[]> = {};
-  for (const pair of qs.split("&")) {
-    const [key, value] = pair.split("=");
-    result[key] = value;
+  const body = qs.startsWith("?") ? qs.slice(1) : qs;
+  if (body === "") return result;
+
+  const decode = (s: string): string => decodeURIComponent(s.replace(/\+/g, " "));
+
+  for (const pair of body.split("&")) {
+    if (pair === "") continue;
+    const eq = pair.indexOf("=");
+    const key = decode(eq === -1 ? pair : pair.slice(0, eq));
+    const value = eq === -1 ? "" : decode(pair.slice(eq + 1));
+    if (Object.prototype.hasOwnProperty.call(result, key)) {
+      const existing = result[key];
+      if (Array.isArray(existing)) {
+        existing.push(value);
+      } else {
+        result[key] = [existing, value];
+      }
+    } else {
+      result[key] = value;
+    }
   }
   return result;
 }
